</style>
<div class="bloom b" style="transform: translateX(calc(var(--bx, 0) * 1px))"></div>
<div class="bloom p"></div>
<div class="bezel"><div class="rimp"></div><div class="rimb"></div></div>
<div class="win"></div>
<svg viewBox="0 0 360 220" width="360" height="220">

  <!-- wall reflection of the lit tubes, soft smear under the sign -->
  <ellipse class="reflect" cx="180" cy="206" rx="160" ry="10" fill="url(#rf)"/>
  <defs>
