    <mask id="mp" maskUnits="userSpaceOnUse" x="-50" y="-50" width="460" height="320"><rect x="-50" y="-50" width="460" height="320" fill="url(#gp)"/></mask>
    <mask id="mb" maskUnits="userSpaceOnUse" x="-50" y="-50" width="460" height="320"><rect x="-50" y="-50" width="460" height="320" fill="url(#gb)"/></mask>
