  }

  setup() {
    this.glassKnob = this.$('.knob-g');
    this.knob = this.$('.knobL');
    this.trkB = this.$('.blue.trk'); this.trkP = this.$('.pink.trk');
    this.wordP = this.$('.wordp'); this.wordB = this.$('.wordb');
    this.onW = [this.$('#onU'), this.$('#onL')];
    this.offW = [this.$('#offU'), this.$('#offL')];
    this.gp = this.$('#gp'); this.gb = this.$('#gb');
    this.spk = this.$$('.spk'); this.flash = this.$('.flash');
    this.s = 0; this.flow = -1; this.tSpark = -1e9;   // (not `dir`: that's a native HTMLElement property)
    this.now = performance.now();
  }

  render(on, instant) {
    this.flow = on ? 1 : -1;
    if (instant) this.s = on ? 1 : 0;
  }

  tick(t, dt) {
    this.now = t;
    const prev = this.s;
    this.s = clamp(this.s + (this.flow * dt) / DUR);
    const s = this.s;
    if ((prev - SPARK_AT) * (s - SPARK_AT) < 0) this.tSpark = t;

    // knob: quick leave, slow drag through the middle while the current changes over, quick arrive
    const x = knobX(s);
    this.glassKnob.setAttribute('cx', x.toFixed(2));
    this.knob.setAttribute('transform', `translate(${x.toFixed(2)} 0)`);

    // the current front: pink pours in from the right end, blue drains to the left
    const mid = bell(0.08, 0.92, s);                       // how "in-between" we are
    const jit = mid * (flk(t, 9) ? 4 : -3);                // the front crackles while it moves
    const F = 345 - 330 * frontG(s) + jit;
    const w = 26 + mid * 24;                               // soft purple overlap at the front
    for (const g of [this.gp, this.gb]) { g.setAttribute('x1', (F - w).toFixed(1)); g.setAttribute('x2', (F + w).toFixed(1)); }

    const hum = 0.95 + 0.05 * Math.sin(t / 37) * Math.sin(t / 113);
    const buzz = 1 - mid * 0.35 * flk(t, 2);              // the tube stutters while the current changes over
    const tube = hum * buzz;
    this.trkB.style.opacity = (tube * 0.85).toFixed(3);
    this.trkP.style.opacity = tube.toFixed(3);

    // knob colour: blue → purple → pink
    const kk = sm(0.2, 0.8, s);
    this.style.setProperty('--kc', KB.map((v, i) => Math.round(lerp(v, KP[i], kk))).join(','));
    this.style.setProperty('--kcc', `rgb(${CB.map((v, i) => Math.round(lerp(v, CP[i], kk))).join(',')})`);
    this.knob.style.opacity = (hum * (1 - mid * 0.25 * flk(t, 5))).toFixed(3);

    // words ride the free space beside the knob; both are half-lit and buzzing in the middle
    const lw = (39 + (x - 56)) / 2, lfree = x - 56 - 39;     // space left of the knob
    const rw = ((x + 56) + 321) / 2, rfree = 321 - (x + 56); // space right of the knob
    const ls = clamp(lfree / 92, 0.55, 1), rs = clamp(rfree / 100, 0.55, 1);
    const place = (els, cx, sc, free) => els.forEach((el) => {
      el.setAttribute('x', cx.toFixed(1));
      el.setAttribute('transform', `translate(${cx.toFixed(1)} 110) scale(${sc.toFixed(3)}) translate(${(-cx).toFixed(1)} -110)`);
      el.setAttribute('opacity', clamp((free - 28) / 40).toFixed(3));
    });
    place(this.onW, lw, ls, lfree);
    place(this.offW, rw, rs, rfree);
    const wOn = sm(0.2, 0.85, s) * (1 - mid * 0.45 * flk(t, 3));
    const wOff = (1 - sm(0.15, 0.8, s)) * (1 - mid * 0.45 * flk(t, 4));
    this.wordP.style.opacity = (wOn * hum).toFixed(3);
    this.wordB.style.opacity = (wOff * hum).toFixed(3);

    // wall + window glow: blue and pink both spill in the middle → violet
    this.style.setProperty('--p', (sm(0.05, 0.75, s) * tube).toFixed(3));
    this.style.setProperty('--b', ((1 - sm(0.25, 0.95, s)) * 0.85 * tube).toFixed(3));
    this.style.setProperty('--bx', ((x - 180) * 0.6).toFixed(1));

    // a stray spark pops off the middle bracket as the knob passes under it
    const e = (t - this.tSpark) / 650;
    this.flash.style.opacity = e >= 0 && e < 1 ? (Math.pow(1 - e, 3) * 0.95).toFixed(3) : 0;
    this.spk.forEach((l, i) => {
      if (e < 0 || e > 1) { l.setAttribute('opacity', 0); return; }
      const ang = -Math.PI * (0.15 + 0.7 * (i / 6)) + Math.sin(i * 12.9) * 0.2;
      const sp = 60 + (i % 3) * 22;
      const px = 180 + Math.cos(ang) * sp * e, py = 51 + Math.sin(ang) * sp * e + 70 * e * e;
      const vx = Math.cos(ang) * sp, vy = Math.sin(ang) * sp + 140 * e;
      l.setAttribute('x1', px.toFixed(1)); l.setAttribute('y1', py.toFixed(1));
      l.setAttribute('x2', (px - vx * 0.11).toFixed(1)); l.setAttribute('y2', (py - vy * 0.11).toFixed(1));
      l.setAttribute('opacity', (1 - e).toFixed(3));
    });
  }
}

